299		if err != nil {
300			return fmt.Errorf("check worktree dirtiness for semantic index: %w", err)
301		}
302		if dirty && !indexOpts.worktree {
303			return errors.New("dirty_worktree: refusing to index uncommitted content without --worktree")
304		}
305		worktreeHashBefore := ""
306		if indexOpts.worktree {
307			worktreeHashBefore, err = worktreeFingerprint(ctx, opts.Runner, repoDir)
308			if err != nil {
309				return fmt.Errorf("fingerprint worktree for semantic index: %w", err)
310			}
311		}
312	
313		var raw []byte
314		var header semanticHeader
315		counts := semanticCounts{}
316		noEgress := false
317		var warnings []semanticWarning
318		for _, warning := range defaultWarnings {
319			warnings = append(warnings, semanticWarning{Code: "default_branch_unknown", Severity: "warning", Effect: "freshness", Detail: warning})
320		}
