408		}
409		snapshotRel := filepath.ToSlash(filepath.Join(semanticDirName, semanticSnapshotsDir, snapshotID, semanticSnapshotName))
410		snapshotPath := filepath.Join(storage.BrainDir, filepath.FromSlash(snapshotRel))
411		if err := rejectExistingSymlinkPathComponents(storage.BrainDir, filepath.FromSlash(snapshotRel)); err != nil {
412			return err
413		}
414		if err := writeFileAtomic(snapshotPath, raw, 0o600); err != nil {
415			return fmt.Errorf("write semantic snapshot: %w", err)
416		}
417		indexOpts.reportPhase("building store")
418		generation, metrics, err := buildSemanticGeneration(storage.BrainDir, repoDir, snapshotID, raw, header, counts, opts.Now().UTC())
419		if err != nil {
420			return err
421		}
422		overlayPath, err := writeSemanticBranchOverlay(ctx, opts.Runner, storage.BrainDir, repoDir, branch, defaultBranch, header.Commit, snapshotRel, opts.Now().UTC())
423		if err != nil {
424			return err
425		}
426		source := &semanticSourceManifest{
427			GeneratedAt:      opts.Now().UTC(),
428			Commit:           header.Commit,
429			Tree:             header.Tree,
430			Branch:           branch,
431			DefaultBranch:    defaultBranch,
432			DirtyWorktree:    dirty,
433			Provider:         header.Provider,
434			ProviderVersion:  header.ProviderVersion,
435			SchemaVersion:    header.SchemaVersion,
436			SnapshotPath:     snapshotRel,
437			StorePath:        filepath.ToSlash(filepath.Join(generation, semanticSQLiteName)),
438			GenerationPath:   generation,
439			MetricsPath:      filepath.ToSlash(filepath.Join(generation, semanticMetricsName)),
440			ParseCachePath:   filepath.ToSlash(filepath.Join(generation, "parse-cache")),
441			OverlayPath:      overlayPath,
442			Symbols:          counts.Symbols,
443			Relations:        counts.Relations,
444			Files:            counts.Files,
445			Warnings:         sanitizeSemanticWarnings(warnings, repoDir),
446			PartialFailures:  sanitizeSemanticWarnings(header.PartialFailures, repoDir),
447			Capabilities:     header.Capabilities,
448			NoEgressVerified: noEgress || indexOpts.skipSem,
449			WorktreeMode:     worktreeMode,
450			WorktreeHash:     worktreeHash,
451		}
452		if err := writeBrainSemanticSource(storage.BrainDir, storage.Key, source); err != nil {
453			return err
454		}
455		if err := writeSemanticSnapshotManifest(storage.BrainDir, snapshotID, source); err != nil {
456			return err
457		}
458		fmt.Fprintf(cmd.OutOrStdout(), "indexed semantic brain: %s\n", storage.BrainDir)
