			summary.Warnings = sanitizeSemanticWarnings(ignore.FilterWarnings(summary.Warnings), repoDir)
			summary.PartialFailures = sanitizeSemanticWarnings(ignore.FilterWarnings(summary.PartialFailures), repoDir)
