		t.Fatal("expected header to be parsed")
	}
	if res.summary == nil {
		t.Fatal("expected trailing summary to be captured")
	}
	if res.counts.Symbols != 1 || res.counts.Relations != 1 || res.counts.Files != 1 {
		t.Fatalf("unexpected counts: %+v", res.counts)
