300	// stdout through scanSemanticStream into out. stdout is never buffered in full;
301	// stderr is captured separately into a bounded buffer. Cancellation flows
302	// through ctx, with a configurable overall deadline and an inactivity timeout so
303	// large repositories are not killed by a fixed short timeout while a hung
304	// provider still aborts.
305	func streamSemanticSnapshot(ctx context.Context, runner CommandRunner, repoDir string, indexOpts semanticIndexOptions, ignoreFiles []string, ignore brainIgnore, out io.Writer) (semanticStreamResult, error) {
306		if ctx == nil {
307			ctx = context.Background()
308		}
309		args := []string{"sem", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network"}
310		for _, path := range ignoreFiles {
311			path = strings.TrimSpace(path)
312			if path == "" {
313				continue
314			}
315			args = append(args, "--ignore-file", path)
316		}
317		if indexOpts.worktree {
318			args = append(args, "--worktree")
319		}
320	
321		overall := indexOpts.timeout
322		if overall <= 0 {
323			overall = semanticSnapshotTimeout
324		}
325		inactivity := indexOpts.inactivityTimeout
326		if inactivity <= 0 {
327			inactivity = semanticSnapshotInactivityTimeout
328		}
329	
330		runCtx, cancel := context.WithTimeout(ctx, overall)
331		defer cancel()
332	
333		var inactivityFired atomic.Bool
334		activity := make(chan struct{}, 1)
335		if inactivity > 0 {
336			go watchSemanticInactivity(runCtx, inactivity, activity, cancel, &inactivityFired)
337		}
338	
339		recordCount := 0
340		cfg := semanticStreamScanConfig{
341			ignore:   ignore,
342			repoDir:  repoDir,
343			progress: indexOpts.progress,
344			onRecord: func(string) {
345				recordCount++
346				select {
347				case activity <- struct{}{}:
348				default:
349				}
350			},
351		}
352	
353		streamer, ok := runner.(CommandStreamer)
354		if !ok {
355			// Fallback for runners without streaming support: buffer via Run, then
356			// process the bytes through the same record-by-record scanner.
