2271	// semanticCompletenessAxis classifies partial provider failures. Failures that
2272	// are exclusively benign parse errors and stay under the tolerance fraction keep
2273	// the axis ok; anything else (a non-parse failure code, an uncountable file set,
2274	// or too many parse errors) degrades the brain.
2275	func semanticCompletenessAxis(source *semanticSourceManifest) staleAxis {
2276		failures := len(source.PartialFailures)
2277		parseErrors := 0
2278		for _, failure := range source.PartialFailures {
2279			if failure.Code == semanticParseErrorCode {
2280				parseErrors++
2281			}
2282		}
2283		if parseErrors == failures && source.Files > 0 {
2284			fraction := float64(failures) / float64(source.Files)
2285			if fraction < semanticParseErrorTolerance {
2286				return staleAxis{State: "ok", Detail: fmt.Sprintf("%d/%d files had tolerated parse errors", failures, source.Files)}
2287			}
2288			return staleAxis{State: "degraded", Detail: fmt.Sprintf("%d partial failures in %.0f%% of files", failures, fraction*100)}
2289		}
2290		return staleAxis{State: "degraded", Detail: strconv.Itoa(failures) + " partial failures"}
